import { spawnSync } from 'node:child_process';
import { existsSync, statSync } from 'node:fs';
import { join } from 'node:path';

export const REFUSED = 2;

/** Resolve a plugin name to its script path. */
export function pluginPath(root, name) {
  return join(root, 'plugins', `${name}.sh`);
}

/** Run a plugin, returning its exit code. */
export function runPlugin(root, name, args = []) {
  const script = pluginPath(root, name);

  if (!existsSync(script)) {
    process.stderr.write(`plugin ${name} is not available\n`);
    return REFUSED;
  }

  if (!statSync(script).isFile()) {
    process.stderr.write(`plugin ${name} is not a runnable file\n`);
    return REFUSED;
  }

  const run = spawnSync('bash', [script, ...args], { encoding: 'utf8' });

  // run.error: bash itself could not be spawned. run.status === null with no
  // error: the plugin process never produced an exit code (e.g. killed by a
  // signal). Neither case gives us a real exit code to propagate, so refuse
  // instead of forwarding whatever spawnSync happened to leave behind.
  if (run.error || run.status === null) {
    process.stderr.write(`plugin ${name} could not be started\n`);
    return REFUSED;
  }

  if (run.stdout) process.stdout.write(run.stdout);
  if (run.stderr) process.stderr.write(run.stderr);
  return run.status;
}

