import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdirSync, rmSync } from 'node:fs';
import { runPlugin, pluginPath, REFUSED } from '../src/launcher.mjs';

const root = process.cwd();

/** Capture what a callback writes to stderr instead of letting it print. */
function captureStderr(fn) {
  const original = process.stderr.write.bind(process.stderr);
  let output = '';
  process.stderr.write = (chunk) => {
    output += chunk;
    return true;
  };
  try {
    fn();
  } finally {
    process.stderr.write = original;
  }
  return output;
}

test('a working plugin runs and its exit code is 0', () => {
  assert.equal(runPlugin(root, 'hello'), 0);
});

test("a failing plugin's own exit code is propagated", () => {
  assert.equal(runPlugin(root, 'fails'), 7);
});

test('a plugin that does not exist is refused', () => {
  assert.equal(runPlugin(root, 'absent'), REFUSED);
});

test('a plugin that does not exist is refused with a message naming it', () => {
  let code;
  const stderr = captureStderr(() => {
    code = runPlugin(root, 'absent');
  });
  assert.equal(code, REFUSED);
  assert.match(stderr, /absent/);
});

test('a plugin path that is a directory is refused, not executed', () => {
  const dir = pluginPath(root, 'dirplugin');
  mkdirSync(dir);
  try {
    let code;
    const stderr = captureStderr(() => {
      code = runPlugin(root, 'dirplugin');
    });
    assert.equal(code, REFUSED);
    assert.match(stderr, /dirplugin/);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

